examples.request:
curl -X POST \
'https://www.wixapis.com/wix-data/v2/collections' \
-H 'Content-Type: application/json' \
-H 'Authorization: <AUTH>' \
-d '{
       "collection": {
         "id": "my-favorite-artists",
         "displayName": "My Favorite Artists",
         "fields": [
           {
             "key": "name", 
             "displayName": "Artist Name", 
             "type": "TEXT"
           },
           {
             "key": "date_of_birth", 
             "displayName": "Date of birth", 
             "type": "DATE"
           },
           {
             "key": "songs_multi_ref",
             "displayName": "Songs",
             "type": "MULTI_REFERENCE",
             "typeMetadata": {
               "multiReference": {
                 "referencedCollectionId": "songs-collection",
                 "referencingFieldKey": "my-favorite-artists",
                 "referencingDisplayName": "Performed by"
               }
             }
           }
         ],
         "permissions": {
           "insert": "ADMIN",
           "update": "ADMIN",
           "remove": "ADMIN",
           "read": "ANYONE"
         }
       }
}'

curl -X POST 'https://www.wixapis.com/wix-data/v2/collections' \
